  { key: 'minimax', label: 'MiniMax' },
  { key: 'moonshotai', label: 'Moonshot AI' },
  { key: 'mistralai', label: 'Mistral' },
  { key: 'z-ai', label: 'Z.AI' },
  { key: 'microsoft', label: 'Microsoft' }
];
const EXCLUDE = /embed|tts|speech|rerank|whisper|vision-only|image-gen/i;
const data = $input.first().json;
const allModels = data.data || [];
const nowSec = Math.floor($now.toSeconds());
const weekAgo = Math.floor($now.minus({ days: 7 }).toSeconds());
function toM(p) {
  const n = parseFloat(p || '0');
  return isNaN(n) ? '?' : '$' + (n * 1e6).toFixed(2);
}
function ctx(n) {
  return n ? Math.round(n / 1000) + 'K' : '?';
}
const viable = allModels.filter(m => m.id && !EXCLUDE.test(m.id) && m.pricing?.prompt !== undefined);
const newThisWeek = viable
  .filter(m => m.created && m.created > weekAgo)
  .sort((a, b) => (b.created || 0) - (a.created || 0))
  .slice(0, 8);
const dateStr = $now.toFormat('yyyy-MM-dd');
let lines = ['---', '## Model Pricing Dashboard', '> Live from OpenRouter - ' + dateStr + ' - All prices in $/1M tokens', ''];
if (newThisWeek.length) {
  lines.push('### New This Week', 'Models added to OpenRouter in the last 7 days:');
  for (const m of newThisWeek) {
    const da = m.created ? Math.floor((nowSec - m.created) / 86400) + 'd ago' : '';
    lines.push('- **' + (m.name || m.id) + '** - ' + toM(m.pricing?.prompt) + ' input / ' + toM(m.pricing?.completion) + ' output - ' + ctx(m.context_length) + ' ctx' + (da ? ' - ' + da : '') + ' - https://openrouter.ai/' + m.id);
  }
  lines.push('');
}
for (const prov of PROVIDERS) {
  const models = viable
    .filter(m => m.id.startsWith(prov.key + '/'))
    .sort((a, b) => (b.created || 0) - (a.created || 0))
    .slice(0, 5);
  if (!models.length) continue;
  lines.push('### ' + prov.label);
  for (const m of models) {
    lines.push('- **' + (m.name || m.id.split('/').pop()) + '** - ' + toM(m.pricing?.prompt) + ' input / ' + toM(m.pricing?.completion) + ' output - ' + ctx(m.context_length) + ' ctx - https://openrouter.ai/' + m.id);
  }
  lines.push('');
}
lines.push('[' + PROVIDERS.map(p => p.label).join(' - ') + ']');

// ── Daily free-model scan (the catalog above is already fetched, so this is free) ──
// Mirrored in research-engine/free_models.py, the manual/eyeball version.
// shortcut: one stealth slot and a 4-model chain keep a total-failure run bounded;
// raise both if stealth models prove reliable.
// Text-in, text-only-out. Excludes music/audio/image generators (e.g. google/lyria-*).
const isText = m => (m.architecture?.input_modalities || []).includes('text') && (m.architecture?.output_modalities || []).join(',') === 'text';
const isZero = m => parseFloat(m.pricing?.prompt || '0') === 0 && parseFloat(m.pricing?.completion || '0') === 0;
const stealth = allModels.filter(m => isText(m) && isZero(m) && !m.id.endsWith(':free') && m.id !== 'openrouter/free');
const tagged = allModels.filter(m => isText(m) && m.id.endsWith(':free')).sort((a, b) => (b.context_length || 0) - (a.context_length || 0));
const freeModels = [...stealth.slice(0, 1).map(m => m.id), 'nvidia/nemotron-3.5-super-vl:free', 'nvidia/nemotron-3.5-lightning:free', ...tagged.map(m => m.id), 'openrouter/free']
  .filter((v, i, a) => a.indexOf(v) === i)
  .slice(0, 4);

return [{ json: { pricingSection: lines.join('\n'), selectedModel: 'openrouter/free', freeModels } }];

// ── Model Fallback Configuration ──────────────────────────────────────────────────────────

// Daily scan from Node 5 (OpenRouter catalog, already fetched). Falls back to the
// known-good pair when the scan is missing or empty.
const SCANNED = $('Node 5: Build Pricing Section').first().json.freeModels || [];
const MODELS = SCANNED.length ? SCANNED : ["nvidia/nemotron-3.5-super-vl:free","nvidia/nemotron-3.5-lightning:free"];
const SAFETY_PATTERNS = ["User Safety:","Response Safety:"];

function normalizeFence(content) {
  if (/```json/i.test(content)) return content;
  const s = content.trimStart();
  if (!s.startsWith('{')) return content;
  let depth = 0, end = -1, inStr = false, esc = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (inStr) {
      if (esc) esc = false;
      else if (ch === '\\') esc = true;
      else if (ch === '"') inStr = false;
      continue;
    }
    if (ch === '"') inStr = true;
    else if (ch === '{') depth++;
    else if (ch === '}') { depth--; if (depth === 0) { end = i + 1; break; } }
  }
  if (end < 0) return content;
  return '```json\n' + s.slice(0, end) + '\n```\n' + s.slice(end);
}

function isResponseInvalid(content) {
  if (!content || content.length < 100) return true;
  for (const p of SAFETY_PATTERNS) {
    if (content.includes(p)) return true;
  }
  const jsonMatch = content.match(/```json([\s\S]*?)```/i);
  if (!jsonMatch) return true;
  try {
    JSON.parse(jsonMatch[1].trim());
  } catch (e) {
    return true;
  }
  return false;
}


