const isoDate = $('Node 2: Get Current Date').first().json.isoDate; const stdoutRaw = $('Node 3: Run Research Engine').first().json.stdout || ''; const DEALS_SEP = '===DEALS==='; const sepIdx = stdoutRaw.indexOf(DEALS_SEP); const researchRaw = sepIdx >= 0 ? stdoutRaw.slice(0, sepIdx) : stdoutRaw; const dealsRaw = sepIdx >= 0 ? stdoutRaw.slice(sepIdx + DEALS_SEP.length) : ''; const research = researchRaw.slice(0, 20000) || 'No research data returned.'; const deals = dealsRaw.slice(0, 20000) || 'No deal data returned today. Do NOT invent any promotion, price, or launch.'; const pricing = $('Node 5: Build Pricing Section').first().json.pricingSection;
