  if (Date.now() - t0 > BUDGET_MS) {
    lastError = 'Time budget exhausted after ' + Math.round((Date.now() - t0) / 1000) + 's';
    break;
  }
  try {
    let response;
    try {
      response = await callModel(model, false);
    } catch (err) {
      // Some free models reject reasoning:false with HTTP 400 "Reasoning is mandatory".
      const errText = (err.message || '') + ' ' + (err.description || '') + ' ' + JSON.stringify(err.response || err.context || '');
      if (!/reasoning is mandatory/i.test(errText)) throw err;
      response = await callModel(model, true);
    }

    const content = normalizeFence(response.choices?.[0]?.message?.content || '');
    if (content !== response.choices?.[0]?.message?.content) response.choices[0].message.content = content;
    if (isResponseInvalid(content)) {
      lastError = 'Model ' + model + ' returned invalid content (empty, safety classifier, or missing ```json metadata block)';
      continue;
