    return [{ json: response }];
  } catch (err) {
    lastError = 'Model ' + model + ' failed: ' + (err.message || String(err));
    continue;
  }
}

throw new Error('All fallback models exhausted. Last error: ' + lastError);

const aiResponse = $input.first().json;
