const metadata_warning = metadata_missing_fields.length ? `⚠️ Metadata incomplete: ${metadata_missing_fields.join(', ')}. Defaults were used; verify this report before relying on it.` : '';
const afterJsonBlockRaw = jsonFenceMatch ? fullText.slice(fullText.indexOf(jsonFenceMatch[0]) + jsonFenceMatch[0].length).trim() : fullText.trim();
function dedupUrlBullets(md) {
  const lines = md.split('\n');
